import{_ as s,o as r,c as t,a2 as a}from"./chunks/framework.ChIlRNAd.js";const m=JSON.parse('{"title":"Archives","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/archives.md","filePath":"fr/guide/archives.md"}'),n={name:"fr/guide/archives.md"};function i(o,e,l,u,g,c){return r(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="archives" tabindex="-1">Archives <a class="header-anchor" href="#archives" aria-label="Permalink to &quot;Archives&quot;">​</a></h1><p>La page <strong>Archives</strong> (<code>/archives</code>) donne accès à la copie locale de vos mails, sauvegardée sur le NAS au format EML. Elle reste consultable même si les mails ont été supprimés de Gmail, et même si le compte Gmail a été déconnecté.</p><p>Cinq onglets : <strong>Mails</strong>, <strong>Contacts</strong>, <strong>Corbeille</strong>, <strong>Rétention</strong>, <strong>Partages</strong>.</p><hr><h2 id="en-tete-et-sauvegarde" tabindex="-1">En-tête et sauvegarde <a class="header-anchor" href="#en-tete-et-sauvegarde" aria-label="Permalink to &quot;En-tête et sauvegarde&quot;">​</a></h2><ul><li>État : « Dernière sauvegarde il y a … · N mails » (ou « Aucune sauvegarde pour l&#39;instant »).</li><li><strong>Sauvegarder sur le NAS maintenant</strong> : sauvegarde les mails du compte pas encore archivés ; la progression s&#39;affiche sous l&#39;en-tête et dans <a href="./activity.html">Activité</a>.</li><li><strong>Exporter (.mbox)</strong> : télécharge les archives du compte au format mbox (lisible par Thunderbird ou Apple Mail). Si une recherche ou un filtre est actif, seuls les résultats chargés sont exportés.</li></ul><p>D&#39;autres façons d&#39;alimenter les archives : <strong>Sauvegarder sur le NAS</strong> dans <a href="./mails.html">Mails</a>, la <strong>Sauvegarde automatique</strong> d&#39;un compte dans <a href="./settings.html#comptes-gmail">Paramètres › Comptes Gmail</a>, les règles « Sauvegarder sur le NAS puis supprimer » et l&#39;import mbox / IMAP de <a href="./settings.html#donnees">Paramètres › Données</a>.</p><hr><h2 id="onglet-mails-rechercher" tabindex="-1">Onglet Mails : rechercher <a class="header-anchor" href="#onglet-mails-rechercher" aria-label="Permalink to &quot;Onglet Mails : rechercher&quot;">​</a></h2><ul><li><strong>Arbre des libellés</strong> (à gauche sur ordinateur) : <strong>Tous les mails</strong> puis les libellés qui contiennent des mails archivés, avec leur nombre.</li><li><strong>Recherche plein texte</strong> : objet, expéditeur, contenu et corps, insensible aux accents, avec <code>&quot;phrase exacte&quot;</code>, <code>-exclure</code> et <code>OR</code>. Les termes trouvés sont surlignés dans l&#39;extrait.</li><li><strong>Tags</strong> (sous les libellés sur ordinateur) : <strong>Tous les tags</strong> puis vos tags, avec leur nombre. Un tag sélectionné filtre la liste et propose <strong>Supprimer le tag « … »</strong>, qui le retire de toutes les archives du compte sans supprimer les mails.</li><li><strong>Filtres</strong> : <strong>Expéditeur</strong>, période (<strong>Du</strong> / <strong>Au</strong>), <strong>Avec pièce jointe</strong>. Sur mobile, ils sont regroupés dans le panneau <strong>Filtres (N)</strong> avec le <strong>Libellé</strong> et le <strong>Tag</strong>, puis <strong>Afficher les résultats</strong>.</li></ul><p>Les résultats (« N résultats ») affichent <strong>Objet</strong>, <strong>Extrait</strong>, <strong>Date</strong>, <strong>Expéditeur</strong>, <strong>Taille</strong>. <strong>Effacer la recherche et les filtres</strong> revient à la liste complète.</p><h3 id="actions" tabindex="-1">Actions <a class="header-anchor" href="#actions" aria-label="Permalink to &quot;Actions&quot;">​</a></h3><ul><li>Menu <code>⋯</code> d&#39;une ligne : <strong>Ouvrir</strong>, <strong>Partager</strong>, <strong>Restaurer dans Gmail</strong>, <strong>Supprimer</strong>.</li><li>Sélection de plusieurs lignes : <strong>Exporter .mbox</strong>, <strong>Tags</strong>, <strong>Restaurer dans Gmail</strong>, <strong>Supprimer</strong>.</li></ul><p><strong>Tags</strong> ajoute ou retire les tags saisis (séparés par des virgules, vos tags existants sont proposés) sur toute la sélection. Les tags restent dans Nid : Gmail ne les voit pas, et ils sont conservés si le mail est archivé à nouveau.</p><p><strong>Supprimer</strong> envoie les archives dans la corbeille des archives, avec un toast « Suppression de N archives dans 10 s » et <strong>Annuler</strong>.</p><h3 id="lecteur-d-archive" tabindex="-1">Lecteur d&#39;archive <a class="header-anchor" href="#lecteur-d-archive" aria-label="Permalink to &quot;Lecteur d&#39;archive&quot;">​</a></h3><p><strong>Ouvrir</strong> affiche le mail archivé : en-têtes, corps (images distantes bloquées, comme dans <a href="./mails.html#lire-un-mail">Mails</a>), pièces jointes téléchargeables, ses <strong>Tags</strong> (retirer un tag d&#39;un clic, en ajouter avec le champ <strong>Ajouter un tag…</strong> puis Entrée) et <strong>Conversation</strong>. Actions : <strong>Partager</strong>, <strong>Restaurer dans Gmail</strong>, <strong>Supprimer</strong>.</p><h3 id="restaurer-dans-gmail" tabindex="-1">Restaurer dans Gmail <a class="header-anchor" href="#restaurer-dans-gmail" aria-label="Permalink to &quot;Restaurer dans Gmail&quot;">​</a></h3><p>Remet les mails archivés dans la boîte Gmail du compte, à partir de leur EML : mêmes en-têtes, même date, mêmes libellés. La restauration tourne en tâche de fond (visible dans <a href="./activity.html">Activité</a>) et une notification annonce le résultat.</p><ul><li>Un mail <strong>encore dans Gmail</strong> est ignoré ; un mail <strong>dans la corbeille Gmail</strong> en est sorti.</li><li>Les libellés système (Boîte de réception, Non lu, Important, catégories…) sont remis tels quels. Un libellé supprimé depuis est recréé sous le même nom. Corbeille, Spam et Brouillons ne sont pas remis.</li><li>Après la restauration, l&#39;archive pointe vers le nouveau mail Gmail : la sauvegarde suivante ne le réarchive pas en double.</li><li>Une archive <strong>chiffrée</strong> ne peut pas être restaurée (la phrase secrète n&#39;est pas conservée) : elle compte comme une erreur.</li><li>Indisponible pour un compte IMAP, et pour un compte Gmail à reconnecter.</li></ul><p>Un mail archivé chiffré affiche « Ce mail est chiffré : son contenu n&#39;est pas lisible ici. » Le chiffrement des archives a été retiré de Nid : remettez ces archives en clair dans <a href="./settings.html#archives-chiffrees">Paramètres › Données</a>.</p><hr><h2 id="partager-un-mail" tabindex="-1">Partager un mail <a class="header-anchor" href="#partager-un-mail" aria-label="Permalink to &quot;Partager un mail&quot;">​</a></h2><p><strong>Partager</strong> ouvre « Partager ce mail » : un lien temporaire, lisible sans compte Nid.</p><ol><li>Choisissez la <strong>Durée de validité</strong> : 1 heure, 24 heures, 3 jours, 7 jours ou 30 jours.</li><li><strong>Créer le lien</strong>, puis copiez-le.</li></ol><p>La fenêtre liste aussi les liens actifs de ce mail (« Expire le … ») avec les boutons copier et révoquer.</p><p>La personne qui ouvre le lien voit le mail (« Mail partagé via lien temporaire »), images distantes bloquées. Un lien expiré, révoqué ou ayant atteint sa limite d&#39;accès affiche « Lien introuvable ».</p><h3 id="onglet-partages" tabindex="-1">Onglet Partages <a class="header-anchor" href="#onglet-partages" aria-label="Permalink to &quot;Onglet Partages&quot;">​</a></h3><p>Tous vos liens actifs : <strong>Objet</strong>, <strong>Expéditeur</strong>, <strong>Expire le</strong>, <strong>Accès</strong> (ouvertures / limite), copier, révoquer. Le nombre de liens actifs est aussi rappelé dans <a href="./settings.html#securite">Paramètres › Sécurité</a>.</p><hr><h2 id="onglet-contacts" tabindex="-1">Onglet Contacts <a class="header-anchor" href="#onglet-contacts" aria-label="Permalink to &quot;Onglet Contacts&quot;">​</a></h2><p>Le carnet d&#39;adresses de l&#39;archive, tiré des en-têtes <strong>De</strong> et <strong>À</strong> des mails archivés (corbeille exclue). Votre propre adresse n&#39;y figure pas.</p><ul><li>Chaque contact affiche son <strong>nom</strong> (un des noms vus dans ses mails), son <strong>adresse</strong>, le nombre de mails archivés où il est <strong>Comme expéditeur</strong> et <strong>Comme destinataire</strong> (champ À, avec d&#39;éventuels autres destinataires) et la date du <strong>Dernier échange</strong>.</li><li>Les contacts avec qui vous échangez le plus apparaissent en premier ; <strong>Rechercher un contact</strong> filtre par nom ou adresse.</li><li>Un clic sur un contact ouvre l&#39;onglet <strong>Mails</strong> filtré sur cet expéditeur.</li></ul><p>Seul le champ <strong>À</strong> est lu : les destinataires en copie (Cc) n&#39;apparaissent pas.</p><hr><h2 id="onglet-corbeille" tabindex="-1">Onglet Corbeille <a class="header-anchor" href="#onglet-corbeille" aria-label="Permalink to &quot;Onglet Corbeille&quot;">​</a></h2><p>Les archives supprimées y restent avant d&#39;être effacées du NAS.</p><ul><li>« N mails dans la corbeille », avec la date <strong>Supprimé le</strong>.</li><li><strong>Restaurer</strong> un mail, ou sélectionnez-en plusieurs puis <strong>Restaurer</strong>.</li><li><strong>Vider la corbeille</strong> : après confirmation, supprime définitivement les mails et leurs pièces jointes du NAS. Irréversible.</li><li>Purge automatique : « Les mails de la corbeille sont supprimés définitivement après N jours » (ou « Purge automatique de la corbeille désactivée »). Les administrateurs règlent ici <strong>Purge automatique</strong> et <strong>Durée avant purge (jours)</strong> pour toute l&#39;instance (voir aussi <a href="./admin.html#systeme">Admin › Système</a>).</li></ul><hr><h2 id="onglet-retention" tabindex="-1">Onglet Rétention <a class="header-anchor" href="#onglet-retention" aria-label="Permalink to &quot;Onglet Rétention&quot;">​</a></h2><p>« Supprime les archives plus anciennes qu&#39;une durée, pour un libellé ou toutes. »</p><ul><li><strong>Nouvelle politique</strong> : <strong>Nom</strong>, <strong>Libellé</strong> (ou <strong>Tous les libellés</strong>), <strong>Supprimer après (jours)</strong>.</li><li>La liste affiche <strong>Nom</strong>, <strong>Libellé</strong>, <strong>Âge</strong> (« Plus de N jours ») et <strong>Dernière exécution</strong> (avec le nombre d&#39;archives supprimées).</li><li><strong>Exécuter maintenant</strong> applique toutes les politiques.</li><li>Menu d&#39;une politique : modifier, supprimer (après confirmation ; les archives déjà supprimées ne reviennent pas).</li></ul><p>Sans politique, les archives sont conservées sans limite de durée.</p>',43)])])}const d=s(n,[["render",i]]);export{m as __pageData,d as default};
